import { revalidateTag } from 'next/cache';
import { getProducts } from '@/lib/products';

export default async function CatalogPage() {
  const products = await getProducts();

  async function syncCatalog() {
    'use server';
    revalidateTag('products');
  }

  return (
    <main style={{ fontFamily: 'system-ui, sans-serif', maxWidth: 900, margin: '0 auto', padding: '2rem' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '1.5rem' }}>
        <h1 style={{ margin: 0, fontSize: '1.5rem' }}>Product Catalog</h1>
        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1.25rem',
              background: '#0070f3',
              color: '#fff',
              border: 'none',
              borderRadius: 6,
              cursor: 'pointer',
              fontSize: '0.9rem',
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.9rem' }}>
        <thead>
          <tr style={{ borderBottom: '2px solid #e5e7eb', textAlign: 'left' }}>
            <th style={{ padding: '0.5rem 0.75rem', color: '#6b7280', fontWeight: 600 }}>SKU</th>
            <th style={{ padding: '0.5rem 0.75rem', color: '#6b7280', fontWeight: 600 }}>Name</th>
            <th style={{ padding: '0.5rem 0.75rem', color: '#6b7280', fontWeight: 600, textAlign: 'right' }}>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id} style={{ borderBottom: '1px solid #f3f4f6' }}>
              <td style={{ padding: '0.75rem', color: '#9ca3af', fontVariantNumeric: 'tabular-nums' }}>
                #{product.id}
              </td>
              <td style={{ padding: '0.75rem' }}>{product.name}</td>
              <td style={{ padding: '0.75rem', textAlign: 'right', fontVariantNumeric: 'tabular-nums' }}>
                ${product.price.toFixed(2)}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  );
}

